57	            long inRotImag = (long)in[j].real() * (long)twid.imag() + ((long)in[j].imag() * (long)twid.real());
58	            // do rounding and shifting
59	            //   printf("raw mult output %ld, %ld\n", inRotReal, inRotImag);
60	            inRotReal = (long)(inRotReal + roundConst) >> (sizeof(twidType) * 8 - 1);
61	            inRotImag = (long)(inRotImag + roundConst) >> (sizeof(twidType) * 8 - 1);
62	            //   printf("after rounding %ld, %ld\n", inRotReal, inRotImag);
