154	         * ++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
155	         */
156	        fft_top_c(din_fix_c, dout_fix_c);
157	        convert2Array<SSR_FFT_R, SSR_FFT_L>(dout_fix_c, dout_fix_c_arr);
158	    }
