163	    // fact that if fixed point data-path bit-widths are appropriate in case of fixed point ssr fft
164	    double snrDBs_ssr_vs_octave = snr<SSR_FFT_R, SSR_FFT_L / SSR_FFT_R>(golden_output, dout_arr);
