53	// SSR_FFT_VIVADO_BEGIN
54	template <int t_L, int t_R, typename T_in, typename T_out>
55	void castArrayS2Streaming(T_in p_inData[t_R][t_L / t_R], hls::stream<SuperSampleContainer<t_R, T_out> >& p_outData) {
56	#pragma HLS INLINE off
57	CONVERT_ARRAY_TO_STREAM_LOOP:
58	    for (int t = 0; t < t_L / t_R; t++) {
59	#pragma HLS PIPELINE II = 1 rewind
60	        SuperSampleContainer<t_R, T_out> temp;
61	
62	        for (int r = 0; r < t_R; r++) {
63	#pragma HLS UNROLL
64	            temp.superSample[r] = p_inData[r][t];
65	        }
66	        p_outData.write(temp);
67	    }
68	}
