86	template <int t_L,
87	          int t_R,
88	          transform_direction_enum transform_direction,
89	          butterfly_rnd_mode_enum buterfly_rnd_mode,
90	          typename T_exp,
91	          typename T_twiddleInType,
92	          typename T_twiddleOutType>
93	void twiddleFactorMulS2S(T_twiddleInType p_inData[t_R],
94	                         T_twiddleOutType p_outData[t_R],
95	                         T_exp p_twiddleTable[],
96	                         int p_k) {
97	    //#pragma HLS INLINE
98	    typedef T_twiddleInType inType;
99	    typedef T_twiddleOutType outType;
100	//#pragma HLS data_pack variable = p_outData
101	//#pragma HLS data_pack variable = p_inData
102	
103	L_TWIDDLE_FACTOR_MUL:
104	    for (int n = 0; n < t_R; n++) {
105	#pragma HLS UNROLL /// Unroll Twiddle Factor Multiplication loop, required for proper implementation of SSR FFT
106	
107	        ap_uint<ssrFFTLog2<t_L>::val> index = n * p_k;
108	        T_exp exp_factor;
109	        if (transform_direction == FORWARD_TRANSFORM) {
110	#ifdef __HLS_SSR_FFT_USE_FULL_WAVE_TWIDDLE_TABLE__
111	            exp_factor = readTwiddleTable<t_L, t_R, ssrFFTLog2<t_L>::val, T_exp>(index, p_twiddleTable);
112	#else
113	            exp_factor = readQuaterTwiddleTable<t_L, t_R, ssrFFTLog2<t_L>::val, T_exp>(index, p_twiddleTable);
114	#endif
115	        }
116	
117	        if (transform_direction == REVERSE_TRANSFORM) {
118	            exp_factor = readQuaterTwiddleTableReverse<t_L, t_R, ssrFFTLog2<t_L>::val, T_exp>(index, p_twiddleTable);
119	        }
120	
121	        complexMultiply(p_inData[n], exp_factor, p_outData[n]);
122	    }
123	}
