136	void fftStageKernelS2S(T_complexExpTableType p_complexExpTable[],
137	                       T_fftTwiddleType p_twiddleTable[TwiddleTableLENTraits<t_L, t_R>::EXTENDED_TWIDDLE_TALBE_LENGTH],
138	                       hls::stream<SuperSampleContainer<t_R, T_in> >& p_fftReOrderedInput,
139	                       hls::stream<SuperSampleContainer<t_R, T_out> >& p_fftOutData_local) {
140	    //#pragma HLS INLINE recursive
141	
142	    const int NO_OF_FFT_STAGES = ssrFFTLog2<t_L>::val / ssrFFTLog2<t_R>::val;
143	    const unsigned int s = NO_OF_FFT_STAGES - stage;
144	    static const bool isFirstStage = (NO_OF_FFT_STAGES == stage);
145	    const int no_of_ffts_in_stage = ssrFFTPow<t_R, s>::val;
146	    const int current_fft_length = t_L / ssrFFTPow<t_R, s>::val;
147	    const int no_bflys_per_fft = current_fft_length / t_R;
148	
149	L_FFTs_LOOP:
150	    for (int f = 0; f < no_of_ffts_in_stage; f++) {
151	    L_BFLYs_LOOP:
152	        for (int k = 0; k < no_bflys_per_fft; k++) {
153	#pragma HLS PIPELINE II = 1 rewind
154	            if (p_fftReOrderedInput.empty()) {
155	                k--;
156	            } else {
157	                T_in X_of_ns[t_R];
158	                T_complexMulOutType complexExpMulOut[t_R];
159	
160	                //#pragma HLS data_pack variable = complexExpMulOut
161	
162	                T_out bflyOutData[t_R];
163	
164	                //#pragma HLS data_pack variable = bflyOutData
165	
166	                SuperSampleContainer<t_R, T_in> temp_super_sample_in = p_fftReOrderedInput.read();
167	            // The following loop should be unrolled for implementation
168	            L_READ_R_IN_SAMPLES:
169	                for (int n = 0; n < t_R; n++) {
170	#pragma HLS UNROLL
171	                    X_of_ns[n] = temp_super_sample_in.superSample[n];
172	                }
173	                Butterfly<t_R> Butterfly_obj;
174	                Butterfly_obj
175	                    .template calcButterFly<t_L, isFirstStage, t_scalingMode, transform_direction, butterfly_rnd_mode>(
176	                        X_of_ns, bflyOutData, p_complexExpTable);
177	                twiddleFactorMulS2S<t_L, t_R, transform_direction, butterfly_rnd_mode>(
178	                    bflyOutData, complexExpMulOut, p_twiddleTable, (k << (ssrFFTLog2<t_L / current_fft_length>::val)));
179	
180	                SuperSampleContainer<t_R, T_out> temp_super_sample_out;
181	            L_WRITE_R_BUTTERFLY_OUT_SAMPLES:
182	                for (int r = 0; r < t_R; r++) {
183	#pragma HLS UNROLL
184	                    temp_super_sample_out.superSample[r] = complexExpMulOut[r];
185	                }
186	                p_fftOutData_local.write(temp_super_sample_out);
187	            }
188	        } // butterflies loop
189	    }     // sub ffts loop
190	}
