237	                    X_of_ns, bflyOutData, p_complexExpTable);
238	            //*******************************************************************************/
239	            // For last stage there is no need to multiply with twiddles since they are unity.
240	            // twiddleFactorMul<t_L, t_R>
241	            //(bflyOutData, complexExpMulOut, p_twiddleTable, k*(t_L / current_fft_length));
242	            // Should be unrolled
243	            //*******************************************************************************/
244	            SuperSampleContainer<t_R, T_out> temp_super_sample_out;
245	        L_WRITE_R_BUTTERFLY_OUT_SAMPLES:
246	            for (int r = 0; r < t_R; r++) {
