302	                SuperSampleContainer<t_R, T_in> temp_super_sample_in = p_fftReOrderedInput.read();
303	            L_READ_R_IN_SAMPLES:
304	                for (int n = 0; n < t_R; n++) {
305	#pragma HLS UNROLL
306	                    X_of_ns[n] = temp_super_sample_in.superSample[n];
307	                }
308	                Butterfly<t_R> Butterfly_obj;
309	                Butterfly_obj
310	                    .template calcButterFly<t_L, isFirstStage, t_scalingMode, transform_direction, butterfly_rnd_mode>(
311	                        X_of_ns, bflyOutData, p_complexExpTable);
312	
313	                twiddleFactorMulS2S<t_L, t_R, transform_direction, butterfly_rnd_mode>
314	
315	                    (bflyOutData, complexExpMulOut, p_twiddleTable, k << (ssrFFTLog2<t_L / current_fft_length>::val));
316	                SuperSampleContainer<t_R, T_out> temp_super_sample_out;
317	            L_WRITE_R_BUTTERFLY_OUT_SAMPLES:
318	                for (int r = 0; r < t_R; r++) {
319	#pragma HLS UNROLL
320	                    temp_super_sample_out.superSample[r] = complexExpMulOut[r];
321	                }
322	                p_fftOutDataLocal.write(temp_super_sample_out);
323	            }
324	        } // butterflies loop
325	    }     // sub ffts loop
