370	void KernelProcessForkS2S<t_forkNumber, t_forkingFactor, t_instanceID>::fftStageKernelLastStageFork(
371	    T_complexExpTableType p_complexExpTable[],
372	    hls::stream<SuperSampleContainer<t_R, T_in> >& p_fftReOrderedInput,
373	    hls::stream<SuperSampleContainer<t_R, T_out> >& p_fftOutDataLocal)
374	
375	{
376	#pragma HLS INLINE off
377	#pragma HLS dataflow
378	
379	    hls::stream<SuperSampleContainer<t_R / t_forkingFactor, T_in> > superSampleStreamArray_in[t_forkingFactor];
380	//#pragma HLS data_pack variable = superSampleStreamArray_in
381	#pragma HLS RESOURCE variable = superSampleStreamArray_in core = FIFO_LUTRAM
382	//#pragma HLS ARRAY_PARTITION variable = superSampleStreamArray_in complete dim = 1
