template <int tp_outputForkingFactor,
          int t_L,
          int t_R,
          int t_instanceID,
          scaling_mode_enum t_scalingMode,
          transform_direction_enum transform_direction,
          butterfly_rnd_mode_enum butterfly_rnd_mode,
          typename T_complexExpTableType,
