60	/*===================================================================================
61	 * Enumeration Defines Saturation Modes for SSR FFT Datapath, Specifically related to
62	 * Butterfly computations. Butterfly computation are essentially Sum of product
63	 * operation and terminate at an adder tree resulting in bit growth. Different options
64	 * are available to deal with this bit growth.
65	 * 1- Do not scale the output and allow progressive bit growth in all FFT stages
66	 * 2- Do not scale the output and allow progressive bit growth but only until the bit-
67	 * width reaches 27 bits which is the max number of bit on ultrascale DSP48 slices for
68	 * multiplier input, so that multiplication operation can fit on these DSPs.
69	 * 3-Scale the outputs after summation so that there is no effective bit-growth
70	 * ===================================================================================*/
71	enum scaling_mode_enum { SSR_FFT_NO_SCALING, SSR_FFT_GROW_TO_MAX_WIDTH, SSR_FFT_SCALE };
72	enum fft_output_order_enum { SSR_FFT_NATURAL, SSR_FFT_DIGIT_REVERSED_TRANSPOSED };
73	enum transform_direction_enum { FORWARD_TRANSFORM, REVERSE_TRANSFORM };
74	enum butterfly_rnd_mode_enum { TRN, CONVERGENT_RND };
75	enum DataTypeEnum { COMPLEX, REAL, IMAG };
